    for op, rc, qc in cols:
        if op=='M':
            if run: s-=go+ge*(run[1]-1); run=None
            s += match if rc==qc else -mm
        else:
            if run and run[0]==op: run=(op,run[1]+1)
            else:
                if run: s-=go+ge*(run[1]-1)
                run=(op,1)
    if run: s-=go+ge*(run[1]-1)
    return s

def cigar_of(cols):
    out=[]; last=None; n=0
    for op,rc,qc in cols:
        o = '=' if op=='M' and rc==qc else ('X' if op=='M' else op)
        if o==last: n+=1
        else:
            if last: out.append(f"{n}{last}")
            last=o; n=1
    if last: out.append(f"{n}{last}")
    return "".join(out)

def all_paths(ref,qry):
    res=[]
    def dfs(i,j,cols):
        if i==len(ref) and j==len(qry):
            res.append(list(cols)); return
        if i<len(ref) and j<len(qry):
            cols.append(('M',ref[i],qry[j])); dfs(i+1,j+1,cols); cols.pop()
        if j<len(qry):
            cols.append(('I',None,qry[j])); dfs(i,j+1,cols); cols.pop()
        if i<len(ref):
            cols.append(('D',ref[i],None)); dfs(i+1,j,cols); cols.pop()
    dfs(0,0,[]); return res

def better(c,b):
    if c[0]!=b[0]: return c[0]>b[0]
    for k in range(1,5):
        if c[k]!=b[k]: return c[k]<b[k]
    return c[5]<b[5]

def brute(ref,qry,p,local):
    match,mm,go,ge=p; best=None
    paths=all_paths(ref,qry)
    for cols in paths:
        ri=qi=0; meta=[]
        for op,rc,qc in cols:
            if op=='M': meta.append((ri,qi)); ri+=1; qi+=1
            elif op=='I': meta.append((None,qi)); qi+=1
            else: meta.append((ri,None)); ri+=1
        if not local:
            cand=(score_columns(cols,match,mm,go,ge),0,0,len(ref),len(qry),cigar_of(cols))
            if best is None or better(cand,best): best=cand
            continue
        L=len(cols)
        for a in range(L):
            for b2 in range(a+1,L+1):
                sub=cols[a:b2]; s=score_columns(sub,match,mm,go,ge)
                if s<=0: continue
                rs=[t[0] for t in meta[a:b2] if t[0] is not None]
                qs=[t[1] for t in meta[a:b2] if t[1] is not None]
                if not rs or not qs: continue
                cand=(s,rs[0],qs[0],rs[-1]+1,qs[-1]+1,cigar_of(sub))
                if best is None or better(cand,best): best=cand
    if local and best is None: return (0,0,0,0,0,"")
    return best

params=[(1,0,0,0),(1,1,0,0),(1,1,1,0),(2,2,2,1),(2,0,1,0),(2,1,0,1),
        (1,2,2,0),(2,2,0,0),(1,0,2,1),(2,1,1,1),(1,1,2,1),(2,2,1,2),(1,0,0,2),(3,0,0,0)]
seqs=["".join(t) for L in range(5) for t in product("AC",repeat=L)]
checked=0
for ref in seqs:
    for qry in seqs:
        for p in params:
            for local in (False,True):
                got=align_pair(SequenceRecord("r",ref),SequenceRecord("q",qry),
                    mode="local" if local else "global",match_score=p[0],
                    mismatch_penalty=p[1],gap_open_penalty=p[2],gap_extend_penalty=p[3])
                got_t=(got["score"],got["reference_start"],got["query_start"],
                       got["reference_end"],got["query_end"],got["cigar"])
                exp=brute(ref,qry,p,local); checked+=1
                assert got_t==exp,(ref,qry,p,local,got_t,exp)
print("all",checked,"cases match brute force")
